import unittest

from border import START_BLOCK, block_border_loops, border_loops
from decode import BadString, decode_string, unpack_tile
from export import (
    encode_string,
    export_block_borders,
    export_borders,
    pack_tile,
    unique_tiles,
    unique_walk,
)

# A real string generated by the tool: three chunks in Wendlewick, marker count 4.
VWH = (
    "TM2IQNWV0gcgODBEpECkQKiBJECswaiBJECswaRAoHAApECswaRAtUKkQKzBpECAZECswaRAqIEswaRAqIE"
    "kQKRAgFk_2n_UMxUjAwUAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA"
)


def ids_for(grids):
    return [(grid_x - 29) * 256 - (71 - grid_y) + 7495 for grid_x, grid_y in grids]


class UnpackTests(unittest.TestCase):
    def test_known_packed_value(self):
        self.assertEqual(unpack_tile(15780148), (50, 50, 36, 22))

    def test_unpack_reverses_pack(self):
        for tile in [(0, 0, 0, 0), (50, 50, 36, 22), (75, 71, 63, 63), (65, 51, 21, 0)]:
            self.assertEqual(unpack_tile(pack_tile(tile)), tile)


class DecodeStringTests(unittest.TestCase):
    def test_two_tile_fixture(self):
        decoded = decode_string("TM2IQVlYXN0MgK0ksMHCAFk_2n_UMxUjAwUAAA")
        self.assertEqual(decoded.name, "east2")
        self.assertEqual(decoded.tiles, [(50, 50, 36, 22), (50, 50, 38, 22)])
        self.assertEqual(decoded.style.hex(), "0164ff69ff50cc548c0c14")

    def test_thirteen_tile_fixture(self):
        text = (
            "TM2IQU1MSw1MQ2r9MMHAREkBRoIARkBBwEjAWT_af9QzFSMDBQAAAAAAAAAAAAAAAAA"
        )
        decoded = decode_string(text)
        self.assertEqual(decoded.name, "51,51")
        self.assertEqual(len(decoded.tiles), 13)
        self.assertEqual({(gx, gy) for gx, gy, _lx, _ly in decoded.tiles}, {(51, 51)})

    def test_surrounding_whitespace_is_ignored(self):
        self.assertEqual(decode_string("  TM2IQVlYXN0MgK0ksMHCAFk_2n_UMxUjAwUAAA\n").name, "east2")

    def test_vwh_is_three_chunks_and_28_markers(self):
        decoded = decode_string(VWH)
        self.assertEqual(decoded.name, "VWH")
        self.assertEqual(len(decoded.tiles), 28)
        self.assertEqual(
            sorted({(gx, gy) for gx, gy, _lx, _ly in decoded.tiles}),
            [(65, 51), (65, 52), (65, 53)],
        )

    def test_vwh_matches_a_fresh_walk_of_those_chunks(self):
        decoded = decode_string(VWH)
        walked = unique_walk(ids_for([(65, 51), (65, 52), (65, 53)]), 4)
        self.assertEqual(set(decoded.tiles), set(walked))


class RoundTripTests(unittest.TestCase):
    def test_encode_then_decode_keeps_the_name_and_tiles(self):
        tiles = [(50, 50, 0, 63), (50, 50, 21, 63), (49, 50, 63, 0)]
        decoded = decode_string(encode_string("round", tiles))
        self.assertEqual(decoded.name, "round")
        self.assertEqual(set(decoded.tiles), set(tiles))

    def test_chunk_export_round_trips(self):
        chunk_ids = ids_for([(47, 51), (48, 49), (48, 50), (48, 51), (49, 50), (50, 50)])
        result = export_borders(chunk_ids, 9, "BQE")
        self.assertIsNone(result.error)
        decoded = decode_string(result.first)
        self.assertEqual(decoded.name, "BQE")
        self.assertEqual(set(decoded.tiles), set(unique_walk(chunk_ids, 9)))

    def test_a_split_export_round_trips_across_both_strings(self):
        result = export_borders([12850], 33, "G")
        self.assertIsNone(result.error)
        first = decode_string(result.first)
        second = decode_string(result.second)
        self.assertEqual(first.name, "G")
        self.assertEqual(second.name, "G2")
        self.assertEqual(len(first.tiles), 127)
        self.assertEqual(len(second.tiles), 1)
        self.assertEqual(
            set(first.tiles) | set(second.tiles), set(unique_walk([12850], 33))
        )

    def test_block_export_round_trips(self):
        blocks = [START_BLOCK, (20, 23)]
        result = export_block_borders(blocks, 4, "ENKLUMPMAN")
        self.assertIsNone(result.error)
        decoded = decode_string(result.first)
        self.assertEqual(decoded.name, "ENKLUMPMAN")
        self.assertEqual(
            set(decoded.tiles), set(unique_tiles(block_border_loops(blocks, 4)))
        )

    def test_a_single_block_decodes_to_its_corners(self):
        result = export_block_borders([START_BLOCK], 2, "E")
        decoded = decode_string(result.first)
        corners = {
            (grid_x * 64 + local_x, grid_y * 64 + local_y)
            for grid_x, grid_y, local_x, local_y in decoded.tiles
        }
        self.assertEqual(corners, {(2856, 3457), (2856, 3606), (3005, 3457), (3005, 3606)})


class BadStringTests(unittest.TestCase):
    def test_missing_prefix(self):
        with self.assertRaises(BadString):
            decode_string("IQVlYXN0Mg")

    def test_not_base64(self):
        with self.assertRaises(BadString):
            decode_string("TM2!!!!")

    def test_unknown_version(self):
        with self.assertRaises(BadString):
            decode_string("TM2AQIDBAUG")

    def test_truncated_after_the_name(self):
        good = encode_string("cut", [(50, 50, 0, 63), (50, 50, 21, 63)])
        with self.assertRaises(BadString):
            decode_string(good[:10])

    def test_empty_body(self):
        with self.assertRaises(BadString):
            decode_string("TM2")


class BorderLoopConsistencyTests(unittest.TestCase):
    def test_every_decoded_tile_sits_on_a_walked_loop(self):
        chunk_ids = [12850, 12594]
        decoded = decode_string(export_borders(chunk_ids, 4, "T").first)
        walked = {tile for loop in border_loops(chunk_ids, 4) for tile in loop}
        self.assertEqual(set(decoded.tiles), walked)


if __name__ == "__main__":
    unittest.main()
